#!/bin/bash
set -e
cd /opt/renostter-erp/cora-api

echo "-- Gravando cora.sqlite (recebido via base64+gzip) --"
cat <<'B64EOF' | base64 -d | gunzip > cora.sqlite

B64EOF

echo "-- Verificando integridade (SHA256) --"
sha256sum cora.sqlite
echo "Esperado: 6b8a640ef7d2728d92357a2778cb19fb46033a6f4a052b0ec0e748fbcce8d221"
